mapper.sql:
where true
  and w.plan_start >= #{from}
  and w.plan_start <= #{to}
  and w.plant_cd = #{plantCd}

  and w.status in ('RELEASED', 'IN_PROGRESS')
  and w.status = #{status}
  and w.item_id = #{itemId}
  and w.order_line_id = #{orderLineId}
  and w.wo_no like '%' || #{keyword} || '%' escape '\'

mapper.select:
select 


 order by w.plan_start desc, w.priority, w.wo_id desc
 limit #{limit}

mapper.update:
update prd_wo
   set status = 'CANCELLED', cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where wo_id = #{id} and row_ver = #{rowVer} and status in ('PLANNED', 'RELEASED')
